VALUES ('rec0JILdTG3IE1pBO', 'extraescolar-acrobacies-mitja-a-partir-d-11-anys-centre-dansa-girona-girona-eixample-girona', 'Acrobàcies Mitjà', 'Centre Dansa Girona', 'recOEFSGYUy1v2uDG', 'Girona - Eixample', 'Dansa', '"Dansa"', 'A partir d''11 anys', '', FALSE, TRUE, FALSE, '20:00 a 21:00 h', 'Dimecres', 'CLAQUÉ: Fes música amb els peus i gaudeix d’una disciplina plena de ritme, coordinació i estil. El complement perfecte a altres tècniques per treballar la musicalitat! Agafa velocitat, coordinació i precisió rítmica convertint els peus en autèntica percussió. El complement perfecte a altres tècniques per treballar la musicalitat!', '1 h ', '', '', '', 'Català', '', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
