VALUES ('rec0sQB6biZGBX11g', 'extraescolar-angles-teens-14-18-anys-eis-girona-girona-sant-narcis-girona', 'Anglès Teens', 'EIS Girona', 'recpX9F9ctmF2Y4tN', 'Girona - Sant Narcís', 'Idiomes', '"Idiomes"', '14-18 anys', 'Des de 78€', FALSE, FALSE, FALSE, 'Diverses opcions', 'Dilluns i dimecres, dimarts i dijous, divendres intensiu', 'A EIS Girona combinem classes dinàmiques amb llibres, eines digitals i seguiment personalitzat. El nostre equip docent adapta el ritme segons el grup i crea un ambient segur per aprendre amb confiança.', '1:30h', '', '', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/clp3MmFkane_E2LMrCbPTA/mRHTNODhETMjpvhM6hirSTNvuLG0auFILOssIsW3RlNI-uY5psyZxaZmUeAJ3nCGMwsv26LjhCulqhXxPesHeiBSja5zKNd8_yMklAjiWzA8da0U0zH-nb_LA37MHxqRsfGwkT0dQuPQloM4wxwPvitQuOIVwNC2JQRjoGNnnuo/ny7DkPkv8y9I2MGRneiYbDm64leWRc0bEoYfLVlsxRs', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/gGVUfdsRvABgagrnXry9Jg/8UVHUe-NKlIiRm6_ufSu0077uO6dvlwnP8ti8A-JtVQaAWVCLdo9XedNAKf_xLrTwGNUDt-v3_qLPpxuge0f3_SGyl6R4Ko3o1J_KEtpb6ckfXTD2ylEoV1SvFCY-gDeZFYRrGyRfytT2wd9dNrHiw/Z1C89zE7Gy-G8gZt0Shw1A_3VcRGsJj6mKKPSxAlv4s', '{}', 'Anglès', 'Extraescolar', '', '', '', '', 'girona')
