VALUES ('rec35rE6VmkXDs7DA', 'extraescolar-ioga-kids-6-11-anys-happy-yoga-girona-girona-eixample-girona', 'Ioga Kids', 'Happy yoga Girona', 'recKEk7mmMaH7QZje', 'Girona - Eixample', 'Ioga', '"Ioga"', '6-11 anys', '38', FALSE, TRUE, FALSE, '17:15 a 18:15 h', 'Dilluns', 'Totes les postures de ioga (àssanes) afavoreixen la salut de la columna, la nostra flexibilitat, la nostra circulació i la nostra capacitat de meditació. Hi ha postures que involucren les cames i que estan destinades a desobstruir el sistema circulatori sanguini, postures de ioga que, a través dels braços, afavoreixen el funcionament del cor, postures de ioga que estimulen i equilibren el sistema endocrí i molts exercicis de respiració iòguica (pranaiama) que aporten salut a la psique i claredat a la ment.', '1h', '', '', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/_sscZWvAv-5JhlgnBpM_wQ/U1IaTxL6HheWu87kIELtOILwh15vl6pS9JGeSPIZozMWfIFjhLWFbN97z1r6p04h9BMvv8ZG0fBbeN6m2Mh0eO1dgQFEazW0gY-2jiyynqC4IOehraJjN56bmVxAd-DlOlElpjkTMF9I30JQnm19V_5RoB-ifPjhRSApLAkjmLZs-pT1RJgeIcyyWDay90Bk/AdEPiGdKARPoS1kP6Sg8EHB2o3pmnNN8gJi7scG8sQc', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/x8ChfEs2W0_NJW2cRyRfmQ/WtKPPdn5tmmGl6oIvyotsIbqGldV9NPHjOVAhVnz0Vnl3Jy4DShfrL23R5rfWIxlb8iuaennVjBYgdrReRNelLSqfRt3mJgY4_yWbEzIpPXXDLFZfpz8TnXBfntf80JCgo3eI-qL0BbCemW7njsxFQ/nbdx3RcsrP8CGGUEObMkLJlEFyx-EBTx0pmgQi9PEAQ', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
