VALUES ('rec97EaVgObftqv8j', 'extraescolar-art-per-a-joves-9-a-13-centre-civic-barri-vell-mercadal-girona-barri-vell-girona', 'Art per a joves', 'Centre Cívic Barri Vell-Mercadal', 'recpG0Qts1G9JA9a6', 'Girona - Barri Vell', 'Creativitat i Expressió', '"Creativitat i Expressió"', '9 a 13', '155 €/l''any', FALSE, FALSE, FALSE, '19:00 a 20:20 h', 'Dilluns', 'Aprendrem i experimentarem amb les diferents tècniques artístiques com per exemple: el dibuix, la pintura, l''escultura i el gravat, entre altres.

