VALUES ('recAUENm6OUtyzjzq', 'extraescolar-angles-per-a-nens-i-nenes-6-12-girolingua-girona-eixample-girona', 'Anglès per a nens i nenes', 'Girolingua', 'recIAWgVhPyjRufJ9', 'Girona - Eixample', 'Idiomes', '"Idiomes"', '6-12', '', FALSE, TRUE, FALSE, 'Divendres de 17.30 a 19.00

