VALUES ('recC3mKAFSaNjyb8v', 'extraescolar-ciclisme-muntanya-iniciacio-4-6-anys-escola-ciclisme-girona-girona-riders-girona-domeny-i-fontajau-girona', 'Ciclisme Muntanya Iniciació', 'Escola ciclisme Girona - Girona Riders', 'recXcvKvWb2CrQyb6', 'Girona - Domeny i Fontajau', 'Esports', '"Esports"', '4-6 anys', 'Des de 36', FALSE, TRUE, FALSE, '17:30 a 18:45 h', 'Dimarts i dijous', 'Des de Girona Riders oferim un extraescolar de ciclisme de muntanya, on es desenvolupa la tècnica específica d’aquest esport. Els infants aprendran a conduir amb seguretat i control la bicicleta.', '75min', 'Fem els grups segons el nivell tècnic i físic de cada participant.', '', '', 'Catala', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/5T-W0ok13Y_FbhdDQuZnyA/zqFNEEduKxCqulFgQ5Iu0ofcI7MJU3UZ5LGlo5JE5mQ40xVYsOAkEXBlsd5awnqIIdVbU7qbqJdcowe9CWqZSR3O2zcVvgsimhbn2hqWgX2MmtGYw3fU_RqmxGvsWCT9wvbPVQg6WXiOaDVmPeKzQG3BLl3Te2ie0VPmBUkW9J0OsQEqZM6CxSOuwLOXA5qH/iBawB_mkqNwiPVDquusdxTqcYpkrBqMAlLOhpGoefV8', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/vivv63ppug0oc6YFoiFjDg/HtTJPNVR__Gk3LJihUWgtxnQWH2pSV3wUxD0Gn1BVYpm5TXsIFR1Pcee2QAz7MwC0UMjVmTAY-hEF3VrINioX2wdqKmgNaaxFps-gEhSNRJ5BbRQ5J5ZxlB9N_O3yslaPy4xjSthLoW_TzwPOsLhOQ/EU3DyO3InIxgPs297dmiCaIUOI5iMgKpDiDnCftFAZo', '{}', 'Ciclisme', 'Extraescolar', '', '', '', '', 'girona')
