VALUES ('recD53PBpJnSlfKBE', 'extraescolar-reforc-escolar-estimulacio-cognitiva-i-estimulacio-del-llenguatge-de-5-a-18-anys-associacio-reach-girona-eixample-girona', 'Reforç Escolar/ Estimulació Cognitiva i Estimulació del Llenguatge', 'Associació Reach', 'recGAl2tXVi7wZkwb', 'Girona - Eixample', 'Reforç escolar', '"Reforç escolar"', 'De 5 a 18 anys', '45 €', FALSE, TRUE, FALSE, 'Tarda', 'Dilluns i divendres ', 'Espai vivencial on els participants aprenen a identificar, comprendre i gestionar les seves emocions de manera saludable. Mitjançant dinàmiques participatives, jocs i activitats adaptades a l''edat, es fomenta l''autoconeixement, l''empatia i el benestar emocional. El treball en grup afavoreix l''intercanvi d''experiències i el desenvolupament personal.', '1:30 h', 'Grups reduïts i per franges d''edat', 'Descompte. per germans', 'Setembre', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/XPC8NVNp8RPBK2_fnS8_mg/EEhJsrSHd2rwEnFBPJZQHtTyOGnV6bsk5Vr6fpN2Gk-nHEiozAa9mAWDxplD3i_DfJBOLXBtKW_CuhkbbCV-oZJj8MJrPbVJi7eI0L-lvxju37oDVz2d4QCKOhR8oXpsuhKnKM2Injrr_8SEhpEj-pxCPPO4SSWgoguUylqNwmyNI76zfcYgxEXVyfrBO4SVw3mex9UUrmamNXFefNbzPxnSkxWUIhrxMAS6xvkrlNhwYRY3j0FM8GBZG86vMq2k/3YcV_44wK6ei9z8HzoIE6-ifP9KpG4ZO1WxxpxY6wXo', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/w_rr9_YHtfl6WL6zOl9dRg/dLo_biJnBy4uiYreU_uxCHhzWaxnQUO_B4QWvo7XhFZLQ7J-79jKEc34Y3zQTzLwt6uP-OqGNFnAmuLZA9weFsSR2vrhzofaOd4t6cuH0YmkucO1-keBlQP8q_WMO0InXK89-j2ZVcdHe7LBrrM69w/skxstkvHY2nD2fqee7qWkB-IgkAosq9BmBKboClRq88', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
