INSERT INTO public.activitats (id, slug, nom, centre, centre_id, barri, categoria, categories, edat, preu, destacada, centre_interessat, destacada_gran, horari, dies, descripcio, durada, alumnes, material, inici, idioma, qui_imparteix, publicada, imatge_url, imatge_thumbnail_url, galeria, subcategoria, tipus, torns, centre_vacances, poblacio_propia, adreca_propia, ciutat)
VALUES ('recDaOYV5dyI3ysag', 'extraescolar-qstura-per-mainada-de-6-a-12-anys-qstura-salt-girona', 'Qstura per mainada', 'Qstura', 'reccxzSeIQJMV4VXV', 'Salt', 'Creativitat i Expressió', '"Creativitat i Expressió"', 'De 6 a 12 anys', '175 €/trimestre', FALSE, TRUE, FALSE, 'De 17:30 a 19:00h', 'Dimarts i dijous.
Dissabte de 12:00 a 13:30h', 'Aquest curs està pensat perquè els nens i nenes s’endinsin en el món tèxtil d’una manera divertida, segura i adaptada a cada etapa. A través d’activitats creatives i útils, descobriran les seves habilitats manuals mentre gaudeixen del procés de crear amb les seves pròpies mans.

Al llarg del curs, els alumnes aprendran a tallar teixits, cosir a mà i utilitzar la màquina de cosir, a més d’experimentar amb diferents tècniques de costura i confecció. Tot plegat amb projectes adaptats a la seva edat i interessos, fomentant l’autonomia, la paciència i la creativitat.

Els temaris són personalitzats segons l’edat i el ritme de cada alumne, amb treballs motivadors que els permeten veure resultats concrets i emportar-se a casa les seves pròpies creacions. Tot això dins d’un ambient molt agradable i acollidor, on aprendre és també passar-s’ho bé. Aprèn, crea i diverteix-te!', '1:30 h', '', 'El preu del curs inclou tots els materials necessaris, però si vols pots portar els teus propis teixits i un costurer bàsic que inclogui: agulles de cosir de diferents mides, agulles de cap, cinta mètrica, didal, tisores per teixit, tisores petites o tallafils, descosidor, guix o bolígraf borrable per marcar.

Si tens dubtes amb el material, consulta''ns i t''ajudarem a preparar el teu costurer!', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/Yvt-AcjO8IZfhgpcz0_b1Q/7W7_G_klMLWAwhsR_9av8r4WEJc8ftoVxgdDsI70PMtZ38v_ub6SQS_d-MxRmHK3_SYUjmWOSLCqf_AK4EHgLjlWEu26Vep-ShgOWWLq14aAB2LGdnliNYoeJ3qNIG47SPrXdBkOzDnQBiy6kyBKkALKU0EnKRvDcPhQtkZmTWE/g-Fn274UwZMvmDpCHysyOt2-QHcWVlB-lW_KGCj4N1I', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/ZAn-oo8wV4rEbdm3JvljWg/kkJyQQRrCQADzudFZrvswtP7-glU4TdOoJ-jlGXo08izL4aaS7M0-hWV3solbYiBoXEsEe0ry9dtLopHXCJyl3EtaFt065cUkkM7UtNq--KQ2gDtnLcf23Q0VTip9EKOFAJQhfTQKkB-3cbcRELJGA/bpllS_0jbmm0IAvaHQJHv7Ila0oavSuyrn9yugBOVKU', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
