VALUES ('recGtQD4PLECpK0zp', 'extraescolar-angles-per-nens-i-nenes-de-8-a-10-anys-eica-girona-eixample-girona', 'Anglès per nens i nenes', 'Eica', 'recHgLj4ryjLawaNz', 'Girona - Eixample', 'Idiomes', '"Idiomes"', 'De 8 a 10 anys', '88', FALSE, FALSE, FALSE, 'De 16:00h a 17:30h o de 17:30h a 19:00h', 'De dilluns a divendres', 'Maximitza els seus dots de comunicació de la forma més efectiva a la nostra escola de Girona. Els nostres cursos d’anglès per nens a partir de 8 anys els brinden una base sòlida de l’idioma per sempre.', '1:30 h', '', '', '', 'Anglès', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/0pFCGOArGLRz5EVomgtafg/xxUqvY3i7PN_iCYMLm5zRp-idmLYAHYekxyCCAtt6UHI2qB1PuGBPbI4JJEfqNtUlxIeodMbvZ1D47nqM1dlXVMrwEi2BaBWVY24gTtXts5ZUQJSop-mW3yrtwHtJRaI9hJNWIo1PG35C-EZRPuSXA7BnLrc3mn1r6Z7OShmWKiq5VcfFrGu3M-oymCCAJKW/UAtaYJFhiZq-p9uih7whjcgKz3gZJwNm_c_pWwMjbnw', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/jpQG8zZCS-TKPYPQGKYdBw/ERPkSxZdhYxzIwWTBBZ0qvbySsk03bofFArnItnv7Vy8AMLoFtv5DCmQN5K1E8p0k8rHLigmQWGs_RCRi_qRZ9lb3Kj1MGOei0ti0izjgmcJoQ-zXACS88aWimo434C5xcaLMSEDGw_datbr9sxIHg/nwOUg8dCBKwd2NTCx9nbNrPk8bKjuBS7XzkBEJ81_RE', '{}', 'Anglès', 'Extraescolar', '', '', '', '', 'girona')
