VALUES ('recH0Xryz2fPYpSgM', 'extraescolar-basquet-3-10-11-anys-geieg-sant-narcis-girona-sant-narcis-girona', 'Bàsquet 3', 'GEiEG - Sant Narcís', 'recifhRNk0AJriirG', 'Girona - Sant Narcís', 'Esports', '"Esports"', '10-11 anys', '37,00', FALSE, FALSE, FALSE, '17:30h a 19:00h', 'Dilluns, dimecres i divendres', 'Uneix-te al món del bàsquet amb el GEiEG, on cada cistella es converteix en una celebració. Amb més de mig segle de trajectòria, la nostra secció continua inspirant jugadores de totes les edats i nivells.', '1:30h', '', 'Per fer aquesta activitat cal ser soci del GEiEG (és un quota addicional al preu de l’activitat)', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/bkKyaYNiNv5FIUAazHQoJg/I-4zhMMylvzcjND7Nj6JKTT-lANJU-mJ1U78EUNwZfj3EHqWbsqjBWqg0Jx8LkDOznu0oxA9BY2RC2wGQBrxlDxE00M6v06tGn2mOuDjpCc3B4T-O8qDPPKOoBORFIVYoR_GuiElHt0ngznrHhPCCrOjZUMdbBOs8yBQgX1Hw_6Mk-ffTgMkqIMaxWO3mHUe/z41gvHiADuLo76uVX-W48nYekDCYZGgvUN0QbGgbgaY', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/0BBxnG8t3sLW7ackgXvWjQ/iJIqQy6lZtHrG-l0wllraD0mKZsPZr9j5MIeAs1MRDiH5W9Ywo8hHOoOAP1EUyDvw618ii1PFPxnrdCWCEtxqejx-sxLm8yuePON5924AtB8yJCmQ8kH_3IBrSVuf0Z65e-xB9mJkkEehehf4qvr-g/IV5DEsIz14OljIkVZ7EJ4cjhqqzorf5M8upY_wWMREc', '{}', 'Bàsquet', 'Extraescolar', '', '', '', '', 'girona')
