VALUES ('recHHh1vRVdjtWZDu', 'extraescolar-dansa-contemporania-3-4-a-partir-de-15-anys-la-central-girona-vista-alegre-carme-girona', 'Dansa Contemporania 3-4', 'La Central', 'recKdVzY8nxvbba5N', 'Girona - Vista Alegre - Carme', 'Dansa', '"Dansa"', 'A partir de 15 anys', '55', FALSE, FALSE, FALSE, '16h a 17''30 ​', 'Dimarts', 'Dansa contemporania per a joves. Tecnica de moviment modern i expressio artistica. Participants en coreografies i espectacles.', '1:30 h', 'Grups reduits', '', 'Octubre', 'Catala', '', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
