VALUES ('recKTHCGZurXwFh8r', 'extraescolar-xines-per-a-nens-preescolars-4-6-anys-institut-xines-siwei-girona-sant-narcis-girona', 'Xinès per a nens preescolars', 'Institut Xinès Siwei', 'recEK5NjkjVX97lNl', 'Girona - Sant Narcís', 'Idiomes', '"Idiomes"', '4-6 anys', '', FALSE, FALSE, FALSE, 'de 17:15h a 18:45h', '1 dia a la setmana', 'Entre els quatre i sis anys, els nostres alumnes aprenen xinès de forma lúdica, a través de jocs, cançons i activitats que els animen a participar a classe i parlar en xinès. Abans que te n''adonis trobaràs al teu fill taral·lejant les nostres cançons o preguntant coses en xinès.', '1:30 h', '', '', '', 'Xinès', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/km3Dmm54PIzbI6SKJ66yEQ/6PDUcavy75g_kKzES4mkuG05QmQ7Ass2qM-758AWhyJMbVmRhwoaVe4K5j1jzHMIlbgRme40UQmz06rUFtGIvWPadH44_zUNuFDklHUnIVTREluu1Z6Ns9KxReKEMAczQk1C7gCoOPhIpKyBqlFAqcWR_5PfjgY1VHNke4Wx_Bw/mEpt6TXX3zqfFLLuDgydDeqyETrEk4bh_s7drp3KQNc', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/hVzqnLgMKMnq8nkZs3JS_Q/OnCB0v9Illn04EsHkpwd8PXhQfLdocQqcsg5iLz3dI02kDGslITo1-2vwASWEZVTXB-EO-DtjFhh8vYv0uTSRkNlEZzuDkWEZSEyVABNK7EvO3XaxeMIqRh37-ZUiIbgit3-fV1op0BWB0A0cnAmXw/7amtOerCg0bixcJIRGHiYvKL5jZwMKzPewsy2qV52eE', '{}', 'Xinès', 'Extraescolar', '', '', '', '', 'girona')
