INSERT INTO public.activitats (id, slug, nom, centre, centre_id, barri, categoria, categories, edat, preu, destacada, centre_interessat, destacada_gran, horari, dies, descripcio, durada, alumnes, material, inici, idioma, qui_imparteix, publicada, imatge_url, imatge_thumbnail_url, galeria, subcategoria, tipus, torns, centre_vacances, poblacio_propia, adreca_propia, ciutat)
VALUES ('recKsaV5xAanGl8UX', 'extraescolar-dansa-creativa-ii-5-6-la-central-girona-vista-alegre-carme-girona', 'Dansa Creativa II', 'La Central', 'recKdVzY8nxvbba5N', 'Girona - Vista Alegre - Carme', 'Dansa', '"Dansa"', '5-6', '42', FALSE, FALSE, FALSE, '17:30-18:30', 'Dimarts', 'Continuacio de Dansa Creativa. Els nens desenvolupen mes consciencia corporal i exploracio del moviment. Expressio artistica a traves de la dansa.

La dansa creativa a La Central és una activitat extraescolar pensada per a infants que volen moure''s, expressar-se i descobrir el seu cos a través del moviment. A diferència de les disciplines de dansa més tècniques, la dansa creativa posa l''accent en la llibertat d''expressió, la imaginació i el joc. Els infants aprenen a escoltar la música, a moure''s en l''espai i a crear les seves pròpies seqüències de moviment de manera espontània i guiada alhora. Les sessions estan pensades per a grups reduïts, amb monitors especialitzats que acompanyen cada infant respectant el seu ritme i la seva personalitat. La Central és un centre d''activitats ubicat al barri de Vista Alegre de Girona, amb una proposta artística i educativa que posa les persones al centre. La dansa creativa és una activitat recomanada per a nens a partir de 3 anys, sense cap requisit previ, ideal per complementar la formació escolar amb una activitat que treballa la coordinació, la confiança i l''expressivitat.', '1h', 'Grups reduits', '', 'Octubre', 'Catala', '', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
