VALUES ('recL5OyTMxOWKmJJo', 'extraescolar-kung-fu-infantil-de-7-a-14-anys-centre-civic-pedret-girona-pedret-girona', 'Kung-Fú Infantil', 'Centre Cívic Pedret', 'recNTyAM5IJg0uoKk', 'Girona - Pedret', 'Esports', '"Esports"', 'De 7 a 14 anys', '15', FALSE, FALSE, FALSE, 'De 18.30-19.30 h', 'Dimarts', 'El Silat de la Grulla Blanca es basa en les arts marcials tradicionals de la Xina i d''Indonèsia. A través de diverses tècniques desenvoluparem un sistema per augmentar la coordinació i millorar la capacitat de concentració. Els nens i nenes aprendran a desenvolupar, en un entorn lúdic, la consciència del propi cos i la força de voluntat.', '1 h', 'Màxim 15 places', '', '', '', 'Ass. d''arts marcials Silat de la Grulla Blanca', TRUE, 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/59wUguMsrON8TZ6519hNGQ/q4wQFGunADljwHCgs7qK-UJ4Nyh52zSuNbqcRazHZvj0h7kTy48gYMMB6zgRdEu6uoX7Vf_M5n3ROx3-_jtKNgtpyhog7aCPVpE5s1QSdIU_6iM_j5SqCeMnLWN5LevPKLqn4v1-qWBIEyOXoKokFqexLLT83iE3N-pJBERIbEdf_y4ygkmtG13kQMJJ13dS/sGignkbscU1Xg3_IZ-_kVIhDxi4dvwYcvYG7dFPE9c4', 'https://v5.airtableusercontent.com/v3/u/55/55/1783540800000/5UKayaL1isuRNxqjrsrg2g/SNOjxYdnEFDQqAVlg0X463NreHMCt7B0LlXsaHiD0JnkKqnKlDjM5rw-jAUAI0cE3Nu7ZY1ffkbVGJfR_byYDHnSiq-w5lHBY0Ghgu0jDiC8-g5to61-fu-KKO5Ry9L1I1q7wDCHNuPXvO_e4lb02Q/lgVOgztQiMOTC_wGM8ivf5i-r8Sm8v_4jWD1vpYVl7w', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
