VALUES ('recRD0HQcEZhvoZKa', 'extraescolar-escola-esportiva-3-6-anys-fedac-sant-narcis-girona-sant-narcis-girona', 'Escola Esportiva', 'FEDAC Sant Narcís', 'recOAhITlxeUs1sRA', 'Girona - Sant Narcís', 'Esports', '"Esports"', '3–6 anys', '33 €/mes · 18 €/mes (1 dia)', FALSE, TRUE, FALSE, '17:00–18:15h', 'Dilluns i Divendres', 'Un espai perquè els més petits comencin a moure''s amb llibertat i confiança. A l''Escola Esportiva de FEDAC Sant Narcís combinen jocs motors, circuits de psicomotricitat i una primera introducció a diferents esports. L''objectiu és que els nens descobreixin les seves capacitats físiques, aprenguin a treballar en equip i agafin hàbits saludables des de ben petits — tot jugant i passant-s''ho bé.', '1:15 h', '', 'Les persones externes a FEDAC Sant Narcís tenen una despesa extraordinària en la quota del primer mes en concepte d''assegurança de 10 €', '', '', '', TRUE, '', '', '{}', 'Psicomotricitat', 'Extraescolar', '', '', '', '', 'girona')
