VALUES ('recTzzsI83qUxIaeN', 'extraescolar-defensa-personal-femenina-a-partir-de-14-anys-centre-civic-pla-de-palau-girona-montilivi-palau-girona', 'Defensa Personal Femenina', 'Centre Cívic Pla de Palau', 'recuVMFgq71oGAMBx', 'Girona - Montilivi-Palau', 'Esports', '"Esports"', 'A partir de 14 anys', '90', FALSE, FALSE, FALSE, 'De 18.45 a 19.45 h', 'Dimecres', 'Amb una instructora dona i experta, aprendràs tot el que necessites saber per defensar-te de possibles agressors, incloent-hi què és la defensa personal femenina i les tècniques d’autoprotecció que són adequades per a qualsevol persona. ', '', '', '', '', '', 'Associació de Veïns de Palau-Sant Pau ', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
